// orchestrator/src/triggers/bugs.ts: triaged Bug tickets start a bug fixer through G3-28's Jira poll. No webhook.
import { CHARTER_SHA } from "../routines/agent-for.js";
import { routineRun } from "../workflows/routine-run.js";
import { QUERIES } from "./schedules.js";

/** To Do, unassigned, triaged into the team, and not opted out or marked as possibly holding customer data. */
export const BUG_JQL = (teamLabel: string, customerDataLabel: string): string =>
  `project = RH AND issuetype = Bug AND statusCategory = "To Do" AND assignee is EMPTY ` +
  `AND labels = "${teamLabel}" AND labels not in ("no-routine", "${customerDataLabel}")`;

/** Call it at worker start, before ensureSchedules, once Security has named the customer-data label. */
export const registerBugQueries = (customerDataLabel: string): void => {
  for (const team of ["fe", "be"] as const) {
    QUERIES.set(`bugfix-${team}`, {
      name: `bugfix-${team}`,
      agent: "bugfix", // startRun: bugfix:RH-1240 on ai-agents-bugfix, so a repeat poll is a no-op
      every: "5 minutes",
      jql: BUG_JQL(team.toUpperCase(), customerDataLabel), // FE / BE: the triage labels proposed in G5-07
      toStart: async (issue) => [
        routineRun,
        { routine: `${team}-bug-fixer`, charterSha: CHARTER_SHA, trigger: { kind: "jira", key: issue.key } },
      ],
    });
  }
};

// ---- G5-13: routine and housekeeping schedules (append to orchestrator/src/triggers/schedules.ts) ----
// Add to the file's imports: agentAttribute from "../fanout.js", agentFor and CHARTER_SHA from
// "../routines/agent-for.js", and `import * as workflows from "../workflows/index.js"`.

interface CronEntry { cron: string; workflow: string; routine?: string; args?: unknown[] }

// Odd minutes, Asia/Jerusalem time; 0-4 = Sunday to Thursday. Each line's owner ticket builds its workflow or charter.
export const CRON: Record<string, CronEntry> = {
  "fe-dead-code": { cron: "17 4 * * 0-4", workflow: "routineRun", routine: "fe-dead-code" }, // G5-31
  "kb-ingest": { cron: "41 6 * * 1", workflow: "routineRun", routine: "kb-ingest" }, // G6-20
  "noise-close": { cron: "23 3 * * *", workflow: "noiseSweep", args: ["fcp"] }, // G5-02
  "team-digest": { cron: "37 6 * * 0-4", workflow: "teamDigest" }, // G5-03
  "trust-ladder": { cron: "51 5 * * *", workflow: "trustLadder" }, // G5-15
  "shadow-report": { cron: "13 7 * * 0", workflow: "shadowReport" }, // G5-16
  "bugfix-taken": { cron: "2-59/5 * * * *", workflow: "bugTakenSweep" }, // a person took the bug: stop its run
};

/** At worker start, after G3-28's ensureSchedules. Safe to run twice: an existing schedule is updated. */
export const ensureCronSchedules = async (client: Client): Promise<string[]> => {
  const made: string[] = [];
  for (const [name, entry] of Object.entries(CRON)) {
    if (!(entry.workflow in workflows)) continue; // its ticket hasn't merged yet
    const agent = entry.routine ? await agentFor(entry.routine).catch(() => undefined) : "orchestrator";
    if (!agent) continue; // no charter yet
    const scheduleId = `sched:${name}`;
    const action = {
      type: "startWorkflow" as const, workflowType: entry.workflow, workflowId: scheduleId, taskQueue: `ai-agents-${agent}`,
      args: entry.routine ? [{ routine: entry.routine, charterSha: CHARTER_SHA, trigger: { kind: "schedule", name } }] : entry.args ?? [],
      ...(entry.routine ? { typedSearchAttributes: agentAttribute(agent) } : {}), // so the kill switch's batch stop finds it
    };
    const spec = { cronExpressions: [entry.cron], timezone: "Asia/Jerusalem" };
    const policies = { overlap: ScheduleOverlapPolicy.SKIP, catchupWindow: "1 hour" }; // no stacking, no backlog replay
    await client.schedule.create({ scheduleId, action, spec, policies }).catch(async (err: unknown) => {
      if (!(err instanceof ScheduleAlreadyRunning)) throw err;
      await client.schedule.getHandle(scheduleId).update((previous) => ({ ...previous, action, spec, policies }));
    });
    made.push(scheduleId);
  }
  return made;
};

// orchestrator/src/activities/bug-taken.ts: a person took a bug while its fixer runs, so stop that run.
import { jira } from "../jira.js"; // G3-28's client; the Jira token stays in the orchestrator
import { temporalClient } from "../temporal.js";
import { stop } from "../workflows/routine-run.js";

const RUNNING_BUG_FIXES = "WorkflowType = 'routineRun' AND Agent = 'bugfix' AND ExecutionStatus = 'Running'";

/** Returns the keys whose runs were told to stop. */
export const stopTakenBugs = async (): Promise<string[]> => {
  const client = await temporalClient();
  const keys: string[] = [];
  for await (const run of client.workflow.list({ query: RUNNING_BUG_FIXES })) {
    keys.push(run.workflowId.slice("bugfix:".length)); // bugfix:RH-1240 → RH-1240
  }
  if (!keys.length) return [];
  const taken = await jira.searchAll(`key in (${keys.join(", ")}) AND assignee is not EMPTY`);
  for (const { key } of taken) {
    const change = (await jira.changelog(key)).filter((h) => h.items.some((i) => i.field === "assignee")).at(-1);
    await client.workflow.getHandle(`bugfix:${key}`).signal(stop, change?.author.accountId ?? "jira");
  }
  return taken.map((i) => i.key);
};

// orchestrator/src/workflows/bug-taken-sweep.ts: workflow code; the sched:bugfix-taken schedule runs it every 5 minutes.
import { peopleApis } from "../policies.js"; // Jira and Temporal calls: retried with back-off, no attempt limit

export async function bugTakenSweep(): Promise<string[]> {
  return peopleApis.stopTakenBugs();
}

