// orchestrator/test/schedules.test.ts: the bug query, the cron table, and ensureCronSchedules run twice.
import assert from "node:assert/strict";
import { test } from "node:test";
import { TestWorkflowEnvironment } from "@temporalio/testing";
import { BUG_JQL } from "../src/triggers/bugs.js";
import { CRON, ensureCronSchedules } from "../src/triggers/schedules.js";

test("the bug query takes only unassigned, triaged bugs and honours both opt-out labels", () => {
  const jql = BUG_JQL("FE", "customer-data");
  for (const part of ["issuetype = Bug", 'statusCategory = "To Do"', "assignee is EMPTY", 'labels = "FE"', '"no-routine"', '"customer-data"']) {
    assert.ok(jql.includes(part), `the JQL is missing ${part}`);
  }
});

test("no schedule runs on the hour or the half hour", () => {
  for (const [name, { cron }] of Object.entries(CRON)) {
    const minute = cron.split(" ")[0] ?? "";
    assert.ok(!["0", "30", "*"].includes(minute), `${name} runs at minute ${minute}`);
  }
});

test("ensureCronSchedules is safe to run twice", async () => {
  const env = await TestWorkflowEnvironment.createLocal({ server: { extraArgs: ["--search-attribute", "Agent=Keyword"] } });
  try {
    const first = await ensureCronSchedules(env.client);
    const second = await ensureCronSchedules(env.client); // a worker restart updates; it never adds a second schedule
    assert.deepEqual(second, first);
    assert.ok(first.includes("sched:bugfix-taken"));
    const sweep = await env.client.schedule.getHandle("sched:bugfix-taken").describe();
    assert.equal(sweep.spec.timezone, "Asia/Jerusalem");
    assert.equal(sweep.action.taskQueue, "ai-agents-orchestrator");
    assert.equal(sweep.policies.overlap, "SKIP");
  } finally {
    await env.teardown();
  }
});
